"use client";

import clsx from "clsx";
import { useNavBar } from "@/components/ui/navigationBar/navigationBar.contexts";
import React, {
  ButtonHTMLAttributes,
  HTMLAttributes,
  useCallback,
  forwardRef,
  useId,
  useEffect,
} from "react";
import {
  Drawer,
  DrawerOptions,
} from "@/components/ui/drawer/drawer.components";

interface Path {
  pathname: string;
  search: string;
  hash: string;
}

export type To = string | Partial<Path>;

/**
 * Page Container component is used to wrap the page content AND NavBar component.
 * @param {React.ReactNode} children - Content to render inside the page container
 * @param {React.HTMLAttributes<HTMLDivElement>} props - Additional HTML div attributes
 *
 * @example
 * ```tsx
 * <PageContainer>
 *   <NavBar>
 *     <h1>Something</h1>
 *   </NavBar>
 *   <PageContent>
 *     <p>Content</p>
 *   </PageContent>
 * </PageContainer>
 * ```
 */
function PageContainer({
  className,
  children,
  ...props
}: HTMLAttributes<HTMLDivElement>) {
  return (
    <div {...props} className={clsx("w-full flex flex-row", className)}>
      {children}
    </div>
  );
}
PageContainer.displayName = "PageContainer";

interface NavBarProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "className"> {
  children: React.ReactNode;
  navBarWidths?: NavBarWidth;
  drawerClassName?: string;
  barClassName?: string;
  drawerOptions?: DrawerOptions;
  drawerStyle?: React.CSSProperties;
  innerClassName?: string;
  floating?: boolean;
}

type NavBarWidth = {
  lg: string;
  sm: string;
};

const defaultNavBarWidths: NavBarWidth = {
  lg: "12em",
  sm: "3.75em",
};

/**
 * Navigation Bar component is used to render the navigation bar.
 * @param {React.ReactNode} children - Content to render inside the navigation bar
 * @param {string} [navBarWidthLg] - Width of the navigation bar when open
 * @param {string} [navBarWidthSm] - Width of the navigation bar when closed
 * @param {string} [drawerClassName] - Classname for the drawer
 * @param {string} [barClassName] - Classname for the navigation bar
 * @param {DrawerOptions} [drawerOptions] - Options for the drawer
 * @param {React.CSSProperties} [drawerStyle] - Style for the drawer
 * @param {string} [innerClassName] - Classname for the inner div
 * @param {boolean} [floating] - Whether the navigation bar is floating
 * @param {React.HTMLAttributes<HTMLDivElement>} props - Additional HTML div attributes
 */
function NavBar({
  children,
  drawerOptions,
  drawerClassName,
  drawerStyle,
  navBarWidths = defaultNavBarWidths,
  style,
  barClassName,
  innerClassName,
  floating = false,
  ...props
}: NavBarProps) {
  const { mode, isOpen, toggleOpen, headerHeightPx } = useNavBar();

  const topOffset = floating ? 0 : headerHeightPx;

  if (mode === "mobile") {
    return (
      <>
        <Drawer
          isOpen={isOpen}
          toggleOpen={toggleOpen}
          options={drawerOptions}
          drawerProps={{ className: drawerClassName, style: drawerStyle }}
        >
          {children}
        </Drawer>
      </>
    );
  }

  return (
    <div
      className={clsx(
        floating ? "fixed" : `sticky`,
        "flex-none",
        "bg-gray-100",
        "overflow-y-auto overflow-x-hidden",
        barClassName,
      )}
      style={{
        top: `${topOffset}px`,
        height: floating ? "auto" : `calc(100vh - ${headerHeightPx}px)`,
        width: isOpen ? navBarWidths.lg : navBarWidths.sm,
        ...style,
      }}
      {...props}
    >
      <div className={clsx("flex flex-col gap-2 p-3", innerClassName)}>
        {children}
      </div>
    </div>
  );
}
NavBar.displayName = "NavBar";

/**
 * Page Content component is used to render the page content.
 * @param {React.ReactNode} children - Content to render inside the page content
 * @param {React.HTMLAttributes<HTMLDivElement>} props - Additional HTML div attributes
 */
function PageContent({
  className,
  children,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div {...props} className={clsx("w-full", className)}>
      {children}
    </div>
  );
}
PageContent.displayName = "PageContent";

interface NavBarHeaderProps extends HTMLAttributes<HTMLDivElement> {
  children: React.ReactNode;
  modeRendered?: "mobile" | "desktop" | "both";
}

/**
 * Nav Header component is used to render the header of the navigation bar.
 * @param {React.HTMLAttributes<HTMLDivElement>} props - Additional HTML div attributes
 */
function NavBarHeader({
  modeRendered = "both",
  children,
  ...props
}: NavBarHeaderProps) {
  const { mode, isOpen } = useNavBar();
  if (modeRendered !== "both" && mode !== modeRendered) return null;

  return (
    <div {...props} data-view-mode={mode} data-open={isOpen}>
      {children}
    </div>
  );
}
NavBarHeader.displayName = "NavBarHeader";

interface NavButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  children: React.ReactNode;
  trigger?: "open" | "close" | "toggle";
}

/**
 * Nav Button component is used to render the button for the navigation bar.
 * @param {string} variant - Variant of the button (open, close, toggle)
 * @param {React.ButtonHTMLAttributes<HTMLButtonElement>} props - Additional HTML button attributes
 */
function NavButton({
  trigger = "toggle",
  className,
  onClick,
  children,
  ...props
}: NavButtonProps) {
  const { toggleOpen, setIsOpen, mode, isOpen } = useNavBar();

  const handleClick = useCallback(
    (e: React.MouseEvent<HTMLButtonElement>) => {
      onClick?.(e);
      switch (trigger) {
        case "toggle":
          toggleOpen();
          break;
        case "close":
          setIsOpen(false);
          break;
        case "open":
          setIsOpen(true);
          break;
      }
    },
    [trigger, isOpen, onClick],
  );

  return (
    <button
      {...props}
      onClick={handleClick}
      className={clsx("cursor-pointer select-none", className)}
      data-variant={trigger}
      data-view-mode={mode}
      data-open={isOpen}
    >
      {children}
    </button>
  );
}
NavButton.displayName = "NavButton";

interface NavItemProps extends HTMLAttributes<HTMLDivElement> {
  children: React.ReactNode;
  navId: string;
  to: To;
}

const NavItem = forwardRef<HTMLDivElement, NavItemProps>(
  ({ children, onClick, to, navId, ...props }, ref) => {
    const { setIsOpen, isOpen, mode, activeNavItemId, registerNavItem } =
      useNavBar();
    const id = useId();

    const handleClick = useCallback(
      (e: React.MouseEvent<HTMLDivElement>) => {
        onClick?.(e);
        if (mode === "mobile") setIsOpen(false);
      },
      [mode, onClick],
    );

    useEffect(() => {
      const href =
        typeof to === "string"
          ? to
          : `${to.pathname ?? ""}${to.search ?? ""}${to.hash ?? ""}`;

      const unregister = registerNavItem({
        id: navId,
        href: href,
      });
      return () => unregister();
    }, [navId, to, registerNavItem]);

    return (
      <div
        {...props}
        onClick={handleClick}
        ref={ref}
        data-active={activeNavItemId === id}
        data-open={isOpen}
        data-view-mode={mode}
      >
        {children}
      </div>
    );
  },
);

export { PageContainer, NavBar, PageContent, NavBarHeader, NavButton, NavItem };

'use client';

import React, {
    useState,
    createContext,
    useContext,
    useMemo,
    useCallback,
    useEffect,
    useRef,
} from 'react';

import useWindowSize from '@/hooks/useWindowSize.hooks';

type NavBarMode = 'mobile' | 'desktop';

interface iNavBarContext {
    isOpen: boolean;
    toggleOpen: () => void;
    setIsOpen: (isOpen: boolean) => void;

    mode: NavBarMode;
    updateMode: (mode: NavBarMode) => void;

    headerElementRef: React.RefObject<HTMLElement | null>;
    headerHeightPx: number;

    activeNavItemId: string;
    registerNavItem: (item: iNavItemRegistration) => () => void;
}

interface iNavItemRegistration {
    id: string;
    href: string;
    requireQuery?: boolean;
    requireHash?: boolean;
}

const NavBarContext = createContext<iNavBarContext | undefined>(undefined);

interface NavBarProviderProps {
    children: React.ReactNode;

    currentPath: string;

    widthSmBreakpointPx?: number;
    widthMdBreakpointPx?: number;
}

function NavBarProvider({
    children,
    currentPath,
    widthSmBreakpointPx = 768,
    widthMdBreakpointPx = 1024,
}: NavBarProviderProps) {
    const { wSize: width } = useWindowSize({
        selector: (s) => s.width,
    });

    const [isOpen, setIsOpen] = useState<boolean>(false);
    const [mode, setMode] = useState<NavBarMode>('mobile');
    const [headerHeightPx, setHeaderHeightPx] = useState<number>(0);
    const [activeNavItemId, setActiveNavItemId] = useState<string>('');

    const headerElementRef = useRef<HTMLElement>(null);
    const headerObserverRef = useRef<ResizeObserver | null>(null);
    const navItemsRef = useRef<Map<string, iNavItemRegistration>>(new Map());

    const toggleOpen = useCallback(() => {
        setIsOpen((prev) => !prev);
    }, []);

    const updateMode = useCallback((newMode: NavBarMode) => {
        setMode(newMode);
    }, []);

    const updateActiveItem = useCallback((path: string) => {
        const { pathname, query, hash } = parsePath(path);

        let bestMatch: { id: string; length: number } | null = null;

        for (const item of navItemsRef.current.values()) {
            const {
                pathname: itemPathname,
                query: itemQuery,
                hash: itemHash,
            } = parsePath(item.href);

            const pathnameMatches =
                pathname === itemPathname ||
                pathname.startsWith(itemPathname + '/');

            if (!pathnameMatches) continue;
            if (item.requireQuery === true && query !== itemQuery) continue;
            if (item.requireHash === true && hash !== itemHash) continue;

            const length = itemPathname.length;

            if (!bestMatch || length > bestMatch.length) {
                bestMatch = { id: item.id, length };
            }
        }

        setActiveNavItemId(bestMatch?.id ?? '');
    }, []);

    const registerNavItem = useCallback((item: iNavItemRegistration) => {
        navItemsRef.current.set(item.id, item);

        return () => {
            navItemsRef.current.delete(item.id);
        };
    }, []);

    useEffect(() => {
        updateActiveItem(currentPath);
    }, [currentPath, updateActiveItem]);

    useEffect(() => {
        const el = headerElementRef.current;
        if (!el) return;

        if (headerObserverRef.current) {
            headerObserverRef.current.disconnect();
            headerObserverRef.current = null;
        }

        const measure = () => {
            setHeaderHeightPx(el.getBoundingClientRect().height);
        };
        const observer = new ResizeObserver(measure);
        observer.observe(el);

        requestAnimationFrame(measure);
        headerObserverRef.current = observer;

        return () => {
            observer.disconnect();
            headerObserverRef.current = null;
        };
    }, []);

    const modifyWindowMode = useCallback(() => {
        if (width === 0) return;

        if (width < widthSmBreakpointPx) {
            setMode('mobile');
            setIsOpen(false);
        } else if (widthSmBreakpointPx < width && width < widthMdBreakpointPx) {
            setMode('desktop');
            setIsOpen(false);
        } else {
            setMode('desktop');
        }
    }, [width, widthSmBreakpointPx, widthMdBreakpointPx]);

    // Set initial mode on mount
    useEffect(() => {
        modifyWindowMode();
    }, []);

    // Update mode when window size changes
    useEffect(() => {
        modifyWindowMode();
    }, [width]);

    const value = useMemo(
        () => ({
            isOpen,
            toggleOpen,
            setIsOpen,
            mode,
            updateMode,
            headerHeightPx,
            headerElementRef,
            activeNavItemId,
            registerNavItem,
        }),
        [
            isOpen,
            mode,
            headerHeightPx,
            headerElementRef,
            activeNavItemId,
            registerNavItem,
        ],
    );
    return (
        <NavBarContext.Provider value={value}>
            {children}
        </NavBarContext.Provider>
    );
}
NavBarProvider.displayName = 'NavBarProvider';

function useNavBar() {
    const context = useContext(NavBarContext);
    if (!context) {
        throw new Error('useNavBar must be used within a NavBarProvider');
    }
    return context;
}

const parsePath = (path: string) => {
    const [pathnameAndQuery, hash = ''] = path.split('#');
    const [pathname, query = ''] = pathnameAndQuery.split('?');

    return {
        pathname,
        query: query ? `?${query}` : '',
        hash: hash ? `#${hash}` : '',
    };
};

export { NavBarProvider, useNavBar };
